import React, { useEffect, useState } from 'react';
import type { Node } from '../core/model.js';
import { rpc } from './state/rpc-client.js';

/*
 * "写回源码" for layers generated by a .tsx component: lists the visual-edit overrides,
 * marks which ones are literal (can go into the JSX source) and which are driven by an
 * expression or by flex/grid layout (they stay overrides), and applies the verified plan
 * through the normal preflight/apply path (one undo).
 */
type PropRow = { id: string; prop: string; status: string; reason?: string };
type Plan = {
  unchanged?: boolean;
  summary?: { written: number; kept: number; file?: string };
  props?: PropRow[];
  candidate?: unknown;
  apply?: unknown;
};
const statusLabel: Record<string, [string, string]> = {
  written: ['可写回', '属性是字面量或缺省，写入 .tsx 后清除覆盖'],
  computed: ['表达式', '属性由表达式计算（如 remap/springTo），保留为覆盖'],
  layout: ['布局', 'flex/grid 布局计算的位置/尺寸，保留为覆盖；请改 style'],
  'changed-output': ['保留', '写成字面量会改变画面（布局或父组件计算），保留为覆盖'],
  'non-literal-value': ['非字面量', '覆盖值不是数字/字符串/布尔，保留为覆盖'],
  spread: ['展开属性', '元素使用 {...props}，无法安全插入，保留为覆盖'],
  'no-target': ['未找到', '源码中没有字面量 id 的元素（可能在别的文件），保留为覆盖'],
  ambiguous: ['重复 id', '多个元素使用同一 id，保留为覆盖'],
  excluded: ['未选', ''],
};

export function JsxWriteBack({
  owner,
  sceneId,
  selectedId,
  revision,
  onError,
}: {
  owner: Node;
  sceneId: string;
  /** Generated node selected inside the component (limits the list), if any. */
  selectedId?: string;
  revision?: string;
  onError: (message: string) => void;
}) {
  const [plan, setPlan] = useState<Plan>(),
    [busy, setBusy] = useState(false),
    [done, setDone] = useState<string>();
  const overrides = Object.keys(owner.overrides ?? {}).length;
  const request = {
    sceneId,
    nodeId: owner.id,
    ...(selectedId && owner.overrides?.[selectedId] ? { ids: [selectedId] } : {}),
  };
  useEffect(() => {
    let live = true;
    setPlan(undefined);
    setDone(undefined);
    if (!overrides) return;
    rpc('jsxWriteBackPlan', { ...request, delivery: 'inline' })
      .then((value) => live && setPlan(value as Plan))
      .catch((e) => live && onError((e as Error).message));
    return () => {
      live = false;
    };
    // Re-plan when the project revision or the selection changes.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [owner.id, sceneId, selectedId, revision, overrides]);
  if (!owner.component?.endsWith('.tsx')) return null;
  const rows = (plan?.props ?? []).filter((r) => r.status !== 'excluded'),
    writable = rows.filter((r) => r.status === 'written').length;
  const apply = async () => {
    setBusy(true);
    try {
      const fresh = (await rpc('jsxWriteBackPlan', request)) as Plan;
      if (fresh.unchanged) return;
      const check = (await rpc('projectPreflight', fresh.candidate)) as {
        valid: boolean;
        diagnostics?: Array<{ severity: string; message: string }>;
      };
      if (!check.valid)
        throw new Error(
          (check.diagnostics ?? [])
            .filter((d) => d.severity === 'error')
            .map((d) => d.message)
            .join('\n') || '预检未通过',
        );
      await rpc('projectApply', fresh.apply);
      setDone(`已写入 ${fresh.summary?.written ?? 0} 项到 ${fresh.summary?.file ?? owner.component}`);
    } catch (e) {
      onError((e as Error).message);
    } finally {
      setBusy(false);
    }
  };
  return (
    <div className="jsx-writeback" data-testid="jsx-writeback">
      <p className="jsx-writeback-hint">
        画面上的调整先作为稳定 ID 覆盖保存；字面量属性可以写回 <code>{owner.component}</code>，画面不变，一步撤销。
      </p>
      {!overrides ? (
        <p className="jsx-writeback-empty">此组件没有覆盖可写回。</p>
      ) : !plan ? (
        <p className="jsx-writeback-empty">正在检查覆盖…</p>
      ) : (
        <ul className="jsx-writeback-list" aria-label="覆盖属性">
          {rows.map((r) => {
            const [label, tip] = statusLabel[r.status] ?? [r.status, r.reason ?? ''];
            return (
              <li key={r.id + r.prop} data-status={r.status} title={r.reason ?? tip}>
                <span className="jsx-writeback-id">{r.id.split('/').at(-1)}</span>
                <span className="jsx-writeback-prop">{r.prop}</span>
                <span className="jsx-writeback-badge" data-kind={r.status === 'written' ? 'literal' : 'override'}>
                  {label}
                </span>
              </li>
            );
          })}
        </ul>
      )}
      <div className="jsx-writeback-actions">
        <button
          className="primary"
          disabled={busy || !writable}
          onClick={() => void apply()}
          title={writable ? `把 ${writable} 项字面量覆盖写入源码` : '没有可写回的字面量覆盖'}
        >
          {busy ? '写回中…' : `写回源码${writable ? ` (${writable})` : ''}`}
        </button>
        {rows.length > writable && (
          <span className="jsx-writeback-kept">{rows.length - writable} 项保留为覆盖</span>
        )}
      </div>
      {done && <p className="jsx-writeback-done">{done}</p>}
    </div>
  );
}
